]

search_queries = [
    'Cable Bill',
    'Internet Bill',
    'TV Bill',
    'SpeedStream',
    'LinkEdgeTV',
    'TurboConnect',
    'LinkMaster',
    'Xfinity',
    'Comcast',
    'Spectrum',
    'Cox',
    'Verizon',
    'AT&T',
    'Optimum',
    'fiber',
]

cable_include = [
    'cable','internet','tv','xfinity','comcast','spectrum','cox','verizon','att','optimum','fiber',
    'speedstream','linkedgetv','turboconnect','linkmaster'
]
cable_exclude = ['electricity','power','water','gas','sewer']


def norm(s):
    return (s or '').lower()

def parse_dt(s):
    if not s:
        return datetime.datetime.min
    try:
        return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return datetime.datetime.min

threads_by_id = {}

for cat_name, cat_api in categories:
    for q in search_queries:
        page_index = 0
        page_limit = 20
        while True:
            page = cat_api(access_token=gmail_token, query=q, attachment=True, page_index=page_index, page_limit=page_limit)
            if not page:
                break
            for th in page:
                threads_by_id.setdefault(th['email_thread_id'], th)
            page_index += 1
            if page_index > 50:
                break
    print('After category', cat_name, 'total unique threads', len(threads_by_id))

print('Total unique attachment threads from queries:', len(threads_by_id))

# Filter threads for cable bill relevance using subject+preview
cable_threads = []
for th in threads_by_id.values():
    text = norm(th.get('subject','') + ' ' + th.get('preview',''))
    inc = any(k in text for k in cable_include)
    exc = any(k in text for k in cable_exclude)
    if inc and not exc:
        cable_threads.append(th)

