# Also show counts by year-month extracted from subject/preview

def extract_ym(text):
    t = norm(text)
    m = re.search(r'(20\d{2})[-/](\d{2})', t)
    if m:
        return m.group(2)+'-'+m.group(1)
    # month name + year
    months = {'jan':1,'feb':2,'mar':3,'apr':4,'may':5,'jun':6,'jul':7,'aug':8,'sep':9,'sept':9,'oct':10,'nov':11,'dec':12}
    m2 = re.search(r'(jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|jun(?:e)?|jul(?:y)?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)\s*(20\d{2})', t)
    if m2:
        mon = months[m2.group(1)[:3]] if m2.group(1)[:3] in months else months.get(m2.group(1)[:4].lower(), None)
        if mon:
            return f'{mon:02d}-{m2.group(2)}'
    return None

from collections import Counter
ym_counts = Counter()
for th in cable_threads_sorted:
    y = extract_ym(th.get('subject','')+' '+th.get('preview',''))
    if y:
        ym_counts[y]+=1

print('Extracted month-year counts (MM-YYYY):')
print(dict(sorted(ym_counts.items())))

