fs_token = apis.file_system.login(username='kat_simp@gmail.com', password=pwds['file_system'])['access_token']

# Helper to paginate thread list

def collect_threads(cat_api, query, attachment=True):
    threads = {}
    page_index = 0
    while True:
        page = cat_api(access_token=gmail_token, query=query, attachment=attachment, page_index=page_index, page_limit=20, sort_by='-created_at')
        if not page:
            break
        for th in page:
            threads[th['email_thread_id']] = th
        page_index += 1
        if page_index > 200:
            break
    return list(threads.values())

categories = {
    'inbox': apis.gmail.show_inbox_threads,
    'archived': apis.gmail.show_archived_threads,
    'spam': apis.gmail.show_spam_threads,
    'snoozed': apis.gmail.show_snoozed_threads if hasattr(apis.gmail,'show_snoozed_threads') else None,
}

# Determine if show_snoozed_threads exists
print('has_snoozed_api', hasattr(apis.gmail, 'show_snoozed_threads'))

queries = ['"Cable Bill"', 'Cable Bill', 'Cable', '"TV" Bill', 'Cable TV']

all_thread_by_id = {}
for q in queries:
    for cat, api in categories.items():
        if api is None:
            continue
        ths = collect_threads(api, q, attachment=True)
        for th in ths:
            all_thread_by_id[th['email_thread_id']] = th
    print('after query', q, 'unique threads so far', len(all_thread_by_id))

all_threads = list(all_thread_by_id.values())
print('total unique threads across queries/categories:', len(all_threads))

# Filter for cable bills via subject/preview heuristics.

def norm(s):
    return (s or '').lower()

cable_threads = []
for th in all_threads:
    subj = norm(th.get('subject',''))
    prev = norm(th.get('preview',''))
    text = subj + ' ' + prev
    # Include if it looks like cable+bill
    if ('bill' in text) and (('cable' in text) or ('tv' in text)):
        # Exclude common non-cable bill terms
        if any(x in text for x in ['electric', 'water', 'gas', 'sewer', 'power', 'electricity', 'phone bill']):
            continue
        cable_threads.append(th)

print('cable_threads after heuristic:', len(cable_threads))

# Sort by created_at desc

def parse_dt(s):
    if not s:
        return datetime.datetime.min
    try:
        return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))
    except Exception:
        return datetime.datetime.min

cable_threads_sorted = sorted(cable_threads, key=lambda x: parse_dt(x.get('created_at')), reverse=True)

print('top 20 cable-related threads (created_at, id, subject):')
